package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaBrxDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("नोंनि अननायखौ आं मिजिंथियो।", "ऐ अल्लाह, बे नोंनि अननाय, जायनि थाखाय आं मिजिं थिदों, बेनिखायनो आंनो मेगन मोख्लाबनायसिमबो गावनिनो नागारना दोन आरो आंनि गासैबो हाबाफोरखौ थि खालाम। नोंनि अनगायै रावबो इसोर गैया।", "दुखु मोनग्रानि दुआ (दा'अ'त अल-मक्रुब)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ दुखु मोनग्रानि दुआ बुंदोंमोन।"),
        "dua_against_enemy_ahzab" to DuaText("सुथुर रौनियाफोरनि बेरेखायै", "ऐ अल्लाह, बिजाबखौ फोसावग्रा, साननायाव गोख्रै। जथाइफोरखौ फेजेन। ऐ अल्लाह, बिसोरखौ फेजेन आरो बिसोरखौ सोलाइ।", "सुथुरनि बेरेखायै-कनफेडारेट्सनि दावहानि दुआ।", "सुथुरनि बेरेखायै पैगंबरनि सल्लल्लाह अलैहि वस्लम दुआ।"),
        "dua_anta_adudi" to DuaText("नों आंनि मददगिरि।", "ऐ अल्लाह, नों आंनि मददगिरि आरो आंनि मददगिरि। आं नोंनि गेजेरजों बिथांखि लायो, आं नोंनि गेजेरजों दावगालामो आरो आं नोंनि गेजेरजों दावहा नांहोयो।", "मोनसे बादायलायनाय एबा मोनसे गिदिर जुजिनायनि सिगां।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा दावहायाव बे बाथ्राखौ बुंदोंमोन।"),
        "dua_ikfinihim" to DuaText("बिसोरनि बेरेखायै आंनो थोजासे।", "ऐ अल्लाह, नों जायखिजाया, आंनो बिसोरनि बेरेखायै थोजासे।", "अनागारिफोरनि गाज्रिनि बेरेखायै-द पिपल अफ द डिचनि सल'आव गथ'नि दुआ।", "अल्लाहा गथ'खौ अनागारिफोरनिफ्राय रैखा खालामदोंमोन।"),
        "dua_qadarullah" to DuaText("जेब्ला माबा गाज्रि जायो।", "बेयो अल्लाहनि बिथोन आरो बिथाङा जायखौ गोसो जायो बेखौ खालामो।", "जेब्ला माबा गाज्रि जायो, अब्ला'इफ ल'बुंनायनि सोलायै।", "'जुदिल'आ शैतननि दरजाखौ खेवयो।"),
        "dua_ala_kulli_hal" to DuaText("मोनफ्रोमबो थासारियाव बाखनाय।", "गासैबो थासारियाव गासिबो बाख्नायनाया अल्लाहनि थाखाय।", "जेब्ला माबा मोजां मोना अब्ला जायो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि मोजां मोनामोन माबा मोनसेखौ मोगा-मोगि जानानै बे बाथ्रा बुंदोंमोन।"),
        "dua_dogs_barking" to DuaText("मोनायाव सैमा खिनाय खोनानो मोनो।", "आं शापित शयताननिफ्राय अल्लाहनि शरण लायो।", "सैमा मोवनायखौ खोनानायानो एबा गधाया हराव बोरलायो।", "जायखौ नोंथाङा नुवा, बिसोर बेखौ नुयो।"),
        "dua_leaving_home_adilla" to DuaText("गोमजोर जानायनिफ्राय रैखा ला।", "ऐ अल्लाह, आं नोंनि सिङाव आश्रय नागिरो, नङाब्ला आं लामा सोलायगोन एबा लामा सोलायगोन, नङाब्ला आं लामा सोलायगोन एबा लामा सोलायगोन, नङाब्ला आं गोरोन्थि खालामगोन एबा अनागारि जागोन, नङाब्ला आं मूर्खथिगोनां आखु एबा मूर्खतागोनां आखुथाय जागोन।", "न'निफ्राय ओंखारबोयोब्ला-उम्म सलामाह (रा.) जों सल'जानाय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा गावनि न'निफ्राय ओंखारबोब्ला बेखौ फरायदोंमोन।"),
        "dua_ascending_descending" to DuaText("गोजौथिं आरो गाहायाव फै।", "अल्लाहआ बयनिख्रुइ देरसिन (जेब्ला गोजौथिं थाङो)।-अल्लाहनो (जेब्ला गाहायाव फैयो) महिमा।", "दावबायनायाव गोजौथिं थांनाय समाव'अल्लाहू अकबर'आरो गाहायाव फैनाय समाव'सुभानल्लाह'बुं।", "दावबायनाय समाव लोगोफोरनि (आर. ए.) सर'।"),
        "dua_traveller_sahar" to DuaText("फुंनि सिगां दावबायारिफोरनि दुआ।", "सासे खोनासंगिरिआ खोनासंदोंमोन दि जों अल्लाहनि बाख्नायनाय आरो जोंनि सायाव बिथांनि मोजां अनथोबफोर दं। जोंनि इसोर, जोंनि लोगो ला आरो जोंनो नोंनि अनथोब हो-(आं बेखौ बुङो) अरनिफ्राय अल्लाहनि शरणाव थां।", "दावबायनायाव, फुंनि सिगां।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा दावबायनायाव बेखौ फुंनि सिगां बुंदोंमोन।"),
        "dua_zawwadakallah" to DuaText("दावबायारिफोरनोः अल्लाहआ तकवा होहो।", "अल्लाहआ नोंनि दावबायनायनि थाखाय तकवा हो, नोंनि पापफोरखौ फोरोङो आरो नों जेरावबो था नोंनो मोजांखौ गोरलै खालामहो।", "जेब्ला सासे दावबायारिखौ बावगारनाय जायो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा सोरखौबा दावबायनो ओंखारनो थाखाय बे दुआखौ होदोंमोन।"),
        "dua_traveller_to_resident" to DuaText("उनथिं थानाय सुबुंफोरनि थाखाय दावबायारि।", "आं नोंखौ अल्लाहनो बावनाय, जायजों फोथायनाया माब्लाबाबो जोबा।", "दावबायारिफ्रा नखरखौ बावगारनाय समाव बुंदोंमोन।", "नखरनि रैखाथिखौ अल्लाहनो बावनाय।"),
        "dua_entering_village" to DuaText("मोनसे सोहोर एबा गामियाव हाबफैनाय।", "हे अल्लाह, स्नि सोरगोफोरनि आरो बैफोर गासै सायानि, स्नि बुहुमनि आरो बैफोर गासैनि, इसोर, असुरफोरनि आरो बिसोर गासिबो लामा-दाखालामग्रा, बार आरो गासिबो गोसारहोनायफोरनि, इसोर! जों नोंखौ बे सोहोरनि मोजां आरो बेनि सुबुंफोरनि मोजांनि थाखाय आरज गाबनाय आरो जों नोंनि सिङाव बेनि गाज्रिनिफ्राय, बेनि सुबुंफोरनि गाज्रि आरो बेयाव थानाय गाज्रिनिफ्राय रैखा नागिरनाय।", "मोनसे सोहोर एबा सोहोराव हाबनायनि सिगां।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा जेब्लाबो गंसे सोहोराव हाबनो गोसो जायो अब्ला बेखौ फरायदोंमोन।"),
        "dua_vehicle_stumbles" to DuaText("जेब्ला गारिआ थाबथाबो।", "अल्लाहनि मुंजों।", "जेब्ला हाजो एबा गारिआ'शयतानआ थैलांनो हागौ'बुंनायनि सोलायै गिदिङो एबा थाबथाबोयो।", "बिस्मिल्लाह बुंनाया शैतानखौ थामफैनि महरसिम गुसेब खालामो।"),
        "dua_ajz_kasal_haram" to DuaText("लोरबांथि आरो बैसो जानायनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं नोंखौ मदद गैयै आरो आलसिया, गिथाव आरो बुज़ुङैनिफ्राय, जिउ आरो थैनायनि आनजादफोरनिफ्राय आरो गोथै खाम्फानि साजानिफ्राय रैखा लुगैदों।", "मोनसे आबुं सानफ्रोमबोनि आश्रय दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमआ गोबां समावनो मोनसे दुआ खालामो।"),
        "dua_sharri_ma_amiltu" to DuaText("आंनि गाज्रि खामानिफोरनिफ्राय रैखा ला।", "ऐ अल्लाह, आं जाय गाज्रि खालामदों आरो जाय गाज्रि मावाखै बेनिफ्राय नोंनाव शरण नागिरो।", "आयशा (रा.) नि बायदिब्ला पैगम्बर सल्लल्लाहु अलैहि वस्लमनि दुआ।", "मा खालामनाय जादोंमोन आरो मा खालामै दोनजादोंमोन मोन्नैनिबो फिथायफोरनिफ्राय रैखाथि।"),
        "dua_jahdil_bala" to DuaText("गोब्राब आनजादफोरनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं नोंखौ गोब्राब जुजिनानिफ्राय, दुखुजों गाग्लोबनायनिफ्राय, गाज्रि बिथोननिफ्राय आरो सुथुरफोरनि गोग्गानायनिफ्राय रैखा नागिरो।", "गोब्राब आनजाद आरो सुथुरफोरनि गोग्गानायनिफ्राय रैखा खालाम।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बे मोनब्रै बाथ्राफोरनिफ्राय आश्रय लादोंमोन।"),
        "dua_fitnat_ghina_faqr" to DuaText("धोन आरो निखावरि आनजादफोरनिफ्राय रैखा ला।", "ऐ अल्लाह, आं नोंनाव आलसिया आरो बैसो जानायनिफ्राय, पाप आरो दाहारनिफ्राय, गोथै खाम्फानि आनजाद आरो साजानिफ्राय, अरनि आनजाद आरो साजानिफ्राय, धोननि आनजाद आरो निखावरि आनजादनिफ्राय रैखा नागिरो।", "गोथै खामफा, जाहान्नाम, धोन आरो निखावरि (दुआनि बाहागो) नि आनजादफोरनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनिफ्राय मोनसे गुवार आश्रय।"),
        "dua_kufr_faqr" to DuaText("फोथायनो हायै आरो निखावरिनिफ्राय रैखा मोननो हानाय।", "ऐ अल्लाह, आं नोंखौ फोथायनो हायै आरो निखावरिनिफ्राय रैखा खालामो आरो फख्रिनि साजानिफ्राय रैखा मोनो। नोंनि अनगा रावबो इसोर गैया।", "खेबथाम फुं आरो बेलासियाव।", "आबु बकराह (रा.) आ पैगम्बर (सा.) खौ बे बाथ्रा बुंनायखौ खोनानायसै।"),
        "dua_sharri_sami" to DuaText("आंनि मोनदांथिफोरनि गाज्रिनिफ्राय रैखा ला।", "ऐ अल्लाह, आं खोनासानायनि गाज्रि, मेगननि गाज्रि, खुगानि गाज्रि, गोसोनि गाज्रि आरो आंनि लुबैनायनि गाज्रिनिफ्राय नोंखौ शरण हो।", "शकल इब्न हुमायद (रा.) नो फोरोंनाय जादोंमोन।", "आथिं-आथिं आरो गावखौ पापनिफ्राय रैखा खालामनो थाखाय मोनसे दुआ।"),
        "dua_hadm_gharaq" to DuaText("हरखाब थैनाय आरो हरखाब जानायनिफ्राय रैखा मोननो हानाय", "ऐ अल्लाह, आं नोंखौ (गंसे बिल्दिंजों) खुरख'जानायनिफ्राय, गोजौनिफ्राय गोग्लैनायनिफ्राय, दैआव गोग्लैनायनिफ्राय, सावनायनिफ्राय, अरनाय आरो बैसो जानायनिफ्राय; सायताननिफ्राय थैनायनि समाव आंखौ लामा गैयै खालामनायनिफ्राय, नोंनि लामाजों खारलांनानै थैनो आरो बिसगोनां दांनायजों थैनोनिफ्राय रैखा नागिरो।", "हरखाब जानाय आरो गाज्रि थैनायनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनिफ्राय मोनसे आश्रय।"),
        "dua_ju_khiyanah" to DuaText("उखैनाय आरो फोथायनो हायैनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं उखैनायनिफ्राय नोंनि सिङाव आश्रय नागिरो, मानोना बियो सासे गाज्रि लोगो, आरो आं फोथायनो हायैनिफ्राय नोंनि सिङाव आश्रय नागिरो, मानोना बियो सासे गाज्रि फोथायग्रा।", "उखैनाय आरो फोथायनो हायैनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनिफ्राय मोनसे आश्रय।"),
        "dua_huda_tuqa" to DuaText("लामा दिन्थिग्रा, गोथारथि, गोथारथि आरो थोजासे।", "ऐ अल्लाह, आं नोंखौ लामा दिन्थि, गोथारथि, गोथारथि आरो गावखौ आबुं खालामनो थाखाय सोङो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे गुसुं, गुवार दुआ।", "धोरोम आरो बे मुलुगनि मोनब्रै गुदि बोरफोर।"),
        "dua_aslih_li_dini" to DuaText("आंनि धोरोम, मुलुग आरो उननि बाथ्राखौ फोसाब।", "ऐ अल्लाह, आंनि धोरोमखौ थि खालाम, जाय आंनि गासैबो हाबाफोरनि रैखाथि, आंनि मुलुगारि जिउखौ थि खालाम, जेराव आंनि जिउ राहाया दं, आरो आंनि आखिराखौ थि खालाम, जेराव आं फैफिनो। आंनि थाखाय गासैबो मोजांनि थाखाय जिउखौ बांहो, आरो थैनायनि थाखाय गासैबो गाज्रिनिफ्राय आराम हो।", "धोरोम फोसाबनाय, बे मुलुग आरो उननि-मोनथामबो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे गुवार दुआ।"),
        "dua_musarrifal_qulub" to DuaText("जोंनि गोसोखौ नोंनि मानिनायसिम सोलाय।", "ऐ अल्लाह, गोसोफोरखौ सोलायग्रा, नोंनि मानिनाय फारसे जोंनि गोसोखौ सोलाय।", "गोसोखौ फोथायनायाव गोख्रों लाखिनो थाखाय मोनसे दुआ।", "गासै सुबुंफोरनि गोसोआ परम करुणानि मोन्नै आसिफोरनि गेजेराव थायो।"),
        "dua_jannah_nar" to DuaText("जाहन्नाखौ सोंनाय, अरनिफ्राय रैखा खालामनाय।", "ऐ अल्लाह, आं नोंखौ सोरगोनि थाखाय सोङो आरो अरनिफ्राय नोंखौ शरण लायो।", "ताशाहहुदनि उनाव एबा जायखिजाया समावनो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुङोः जोंनि दुआफोराबो बेनि सोरगिदिं गिदिङो।"),
        "dua_khayri_kullih" to DuaText("गासिबो मोजां, दा आरो उनाव।", "ऐ अल्लाह, आं नोंखौ गासिबो मोजांनि थाखाय बिनायदों-हरखाब आरो गोबाव जानाय, जायखौ आं मिन्थिदों आरो जायखौ आं मिन्थिाखै-आरो आं नोंखौ गासिबो गाज्रिनिफ्राय-हरखाब आरो गोबाव जानायनिफ्राय, जायखौ आं मिन्थिदों आरो जायखौ आं मिन्थिाखै। ऐ अल्लाह, आं नोंखौ सोरगोनि थाखाय बिनायदों आरो जाय सोदोबफोर आरो हाबाफोरा आंखौ बिनि खाथियाव लाबोयो, आरो आं अरनिफ्राय आरो जायखिजाया सोदोबफोर आरो खामानिफोरनिफ्राय नोंखौ शरण लायो जाय आंखौ बिनि खाथियाव लाबोयो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा आयशा (रा) नो बे गुवार दुआखौ फोरोंदोंमोन।", "मोनसे दुआ जाय गासैबो मोजांखौ बुथुमो।"),
        "dua_ihdini_saddidni" to DuaText("आंनो लामा दिन्थि आरो आंखौ मोजाङै लाखि।", "ऐ अल्लाह, आंनो लामा दिन्थि आरो आंखौ थि लामायाव दोन।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बेखौ आली (रा.) नो फोरोंदोंमोन।", "लामा लामा दिथा होनाय महरै लामा दिन्थिग्रा आरो बाणनि थोंगोरथि महरै सादादखौ सान।"),
        "dua_hubbaka" to DuaText("अल्लाहनि अननायखौ सों।", "ऐ अल्लाह, आं नोंखौ नोंनि अननाय, नोंखौ मोजां मोनग्राफोरनि अननाय आरो बैफोर खामानिफोरनि थाखाय बिनायदों जाय आंखौ नोंनि अननायसिम लाबोयो। ऐ अल्लाह, नोंनि अननायखौ आंनि, आंनि नखर आरो गुसु दैनिख्रुइ आंनि थाखाय बांसिन अननाय खालाम।", "दाउदनि दुआआ पैगम्बर सल्लल्लाहु अलैहि वस्लमजों सोमोन्दो गोनां।", "अल्लाहनि अननाया बयनिख्रुइ देरसिन धोन।"),
        "dua_filal_khayrat" to DuaText("मोजां खालामनाय आरो गाज्रिखौ नागारनाय।", "ऐ अल्लाह, आं नोंखौ मोजां खामानि मावनो, गाज्रि खामानिफोरखौ नागारनो आरो निखावरिफोरखौ मोजां मोनहोनो, आरो नों आंखौ क्षमा खालाम आरो आंनो अननाय होनो थाखाय बुंबाय। आरो जेब्ला नों मोनसे हारिनि थाखाय मोनसे आनजाद लानो सानदों, अब्ला आंखौ आनजाद नायजासे लाना थां। आं नोंखौ नोंनि अननाय, नोंखौ मोजां मोनग्राफोरनि अननाय आरो हाबाफोरनि अननाय जाय आंखौ नोंनि अननायनि खाथियाव लाबोयो।", "अल्लाहआ बे दुआखौ पैगंबर सल्लल्लाहु अलैहि वसल्लमनो मोनसे सिमांआव फोरोंदोंमोन।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुंदोंमोनः बेयो सैथो, बेनिखायनो बेखौ सोलों आरो बेखौ फोरों।"),
        "dua_bi_ilmikal_ghayb" to DuaText("जिउआ मोजां जानानैबो आंनो थांना थानो हो।", "ऐ अल्लाह, नों नायजायैनि गियान आरो सोरजिनायनि सायाव नोंनि गोहोजों-जेब्लासिम नों आंनि थाखाय जिउआ साबसिन मोन, आरो जेब्ला नों मिन्थिगोन दि थैनायआ आंनि थाखाय साबसिन। ऐ अल्लाह, आं नोंखौ गावारि आरो रायजोआरि महरै, गोजोनथि आरो रागायाव सैथोनि सोदोब, आरो निखावरि आरो धोनआव गुरैथिनि थाखाय नोंखौ गिनांगौ।", "अम्मार इब्न यासिर (आर. ए.) नि आरज दुआ (जागायजेन्नाय बाहागो)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे दुआखौ आरज गाबनायाव खालामदोंमोन।"),
        "dua_ism_azam_mannan" to DuaText("इसम-ए-आजमः अल-मन्नान।", "ऐ अल्लाह, आं नोंखौ सोंदों, मानोना गासिबो बाख्नायनाया नोंनि; नोंनि अनगा रावबो इसोर गैया, सोरखौ मदद होयो, सोरखौ सोरखौ सोरखौ सोरखि आरो सोरखौ सोरखि खालामो। ऐ गेदेमा आरो मान होग्रानि, ऐ अराय जिउ खांग्रानि, ऐ खांग्रानि!", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुंदोंमोन दि बे मानसिया अल्लाहनि देरसिन मुंजों दुआ बानायदोंमोन।", "बे मुंजों बानायनाय मोनसे दुआनि फिन होनाय जायो।"),
        "dua_ism_azam_ahad_samad" to DuaText("इसम-ए-आजमः अल-अहद अस-समद।", "ऐ अल्लाह, आं नोंखौ सोंदों, मानोना आं साखि होयो दि नों अल्लाह; नोंनि अनगा रावबो इसोर गैया, सासे, गावखौ हमथानाय, जाय जोनोम जायाखै आरो जोनोम जायाखै, आरो बिनि रुजुनायाव रावबो गैया।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बुंदोंमोन दि बे मानसिया अल्लाहखौ बिथांनि देरसिन मुंजों सोंदोंमोन।", "जेब्ला बिनि गेजेरजों सोंदोंमोन, बियो होयो; जेब्ला बिनि गेजेरजों लिंहरनाय जायो, बियो फिन होयो।"),
        "dua_thabbitni_hadiyan" to DuaText("आंखौ गोख्रों, लामा दिन्थिग्रा आरो लामा दिन्थिग्रा खालाम।", "ऐ अल्लाह, आंखौ गोख्रों खालाम आरो आंखौ ओरैबायदि खालाम जाय लामा दिन्थिफुङो आरो लामा दिन्थिफुङो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा जारिर (रा) नि थाखाय बे दुआखौ बानायदोंमोन (गावनि थाखाय'थाबितनी'बुं)।", "जारिर (आर. ए.) नि गुबै दुआआव'थाबित-हु'सोदोबफोरखौ बाहायनाय जायो।"),
        "dua_rabbighfir_tub_alayya" to DuaText("आंखौ बावगार आरो आंनि अन'जिखौ नाजाव।", "आंनि इसोर, आंखौ क्षमा खालाम आरो आंनि अननायखौ आजाव। थारैनो, नों अननायनि दारुन, अनजाथाव।", "मोनसे जिरायनायाव सेजौ खेब-पैगंबर सल्लल्लाहु अलैहि वस्लमनि हुदा।", "लोगोफोरा पैगंबर सल्लल्लाहु अलैहि वस्लमखौ मोनसे जिरायनायाव सेजौ खेब बुंनायखौ सानदोंमोन।"),
        "dua_rafiq_ala" to DuaText("थैनाय सुबुंनि दुआ।", "ऐ अल्लाह, आंखौ बावगार, आंखौ अननाय आरो गोजौसिन लोगोजों आंजों था।", "पैगंबरनि जोबथा दुआआ-बेरामगोनां सुबुंनि थाखाय गावनि थाखाय बुं।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि रुंसारि जानायनि समाव बे दुआखौ खालामदोंमोन।"),
        "dua_la_bas_tahur" to DuaText("बेरामिया गोजोनः गोथार खालामनाय।", "जेबो खहा गैया; जुदि अल्लाहआ गोसो होयो अब्ला बेयो मोनसे गोथार खालामनाय (पापफोरनिफ्राय)।", "जब्राफोरखौ गोजोनहोनो जेब्ला दावबायहैयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेराम जानायफोरखौ नायहैनायाव बे बाथ्रा बुंदोंमोन।"),
        "dua_talqeen" to DuaText("थैनायनि थाखाय तालकीन", "अल्लाहनि अनगा रावबो सिबिजानायनि मोन्थाइ गैया।", "सासे थैबाय थानाय सुबुंनि खाथियाव कलिमा फराय (बिसोरखौ बेखौ बुंनो नारसिननाङा)।", "जायहा जोबथा सोदोबफोरा'ला इलाहा इल्लल्लाह', बियो सोरगोआव हाबगोन (आबु दाउद 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("थैनायनि थाखाय लुबैनायनि सोलायै", "ऐ अल्लाह, जेब्लासिम आंनि थाखाय जिउआ साबसिन, अब्लासिम आंखौ थांना लाखि आरो जेब्ला थैनायनि थाखाय मोजांसिन जायो अब्ला आंखौ लां।", "गोब्राब थासारियाव थैनायनि थाखाय लुबैनायनि सोलायै।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा थैनायनि थाखाय लुबैनायखौ होबथायो आरो बेनि सोलायै बेखौ फोरोङो।"),
        "dua_for_one_i_cursed" to DuaText("सोरबा सासेनि थाखाय आं सोदोबफोरजों दुखु होयो।", "ऐ अल्लाह, जाय फोथायगिरिखौ आं लाजि होदों, बिखौ फिन फिन फिन फिन फिननाय सानाव गावनि थाखाय नोंनि खाथियाव सौहैनायनि राहा खालाम।", "सोरबा सासेजों नों रागा जोंनानै गाज्रि रायज्लायदोंमोन।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे दुआ।"),
    )
}
